    sys.stderr.write(f"error: a value is required for '{opt} <{name}>' but none was supplied\n\nFor more information, try '--help'.\n")
    sys.exit(2)

def duplicate(opt):
    sys.stderr.write(f"error: the argument '{opt}' cannot be used multiple times\n\nUsage: executable [OPTIONS] [INPUT]\n\nFor more information, try '--help'.\n")
    sys.exit(2)

def invalid_value(opt, val, reason):
    name = VALUE_NAMES.get(opt, opt.lstrip('-'))
    sys.stderr.write(f"error: invalid value '{val}' for '{opt} <{name}>': {reason}\n\nFor more information, try '--help'.\n")
    sys.exit(2)


def parse_args(argv):
    opt = Options()
    seen = set()
    positionals = []
    i = 0
    after_dd = False
    while i < len(argv):
        a = argv[i]
        if after_dd:
            positionals.append(a); i += 1; continue
        if a == '--':
            after_dd = True; i += 1; continue
        if a in ('-h', '--help'):
            sys.stdout.write(HELP); sys.exit(0)
        if a in ('-V', '--version'):
            sys.stdout.write('fblog 4.17.0\n'); sys.exit(0)

        # support --option=value for long value options
        attached_value = None
        if a.startswith('--') and '=' in a:
            optname, attached_value = a.split('=', 1)
        else:
            optname = LONG_FOR_SHORT.get(a, a)

        def get_value():
            nonlocal i, attached_value
            if attached_value is not None:
                return attached_value
            if i + 1 >= len(argv):
                value_required(optname)
            i += 1
            return argv[i]

        if optname in SINGLE_FLAGS and optname in seen:
            duplicate(optname)

        if optname in ('--additional-value',):
            opt.additional.append(get_value())
        elif optname == '--config-file':
            seen.add(optname); opt.config_file = get_value()
        elif optname == '--message-key':
            opt.message_keys.append(get_value())
        elif optname == '--print-lua':
            seen.add(optname); opt.print_lua = True
        elif optname == '--time-key':
            opt.time_keys.append(get_value())
        elif optname == '--level-key':
            opt.level_keys.append(get_value())
        elif optname == '--map-level':
            val = get_value()
            if '=' not in val:
                invalid_value('--map-level', val, "missing '='")
            frm, to = val.split('=', 1)
            opt.map_levels.append((frm, to))
        elif optname == '--dump-all':
            seen.add(optname); opt.dump_all = True
        elif optname == '--excluded-value':
            opt.excluded.append(get_value())
        elif optname == '--with-prefix':
            seen.add(optname); opt.with_prefix = True
        elif optname == '--filter':
            seen.add(optname); opt.filter_expr = get_value()
        elif optname == '--no-implicit-filter-return-statement':
            seen.add(optname); opt.no_implicit_filter_return_statement = True
        elif optname == '--main-line-format':
            seen.add(optname); opt.main_line_format = get_value()
        elif optname == '--additional-value-format':
            seen.add(optname); opt.additional_value_format = get_value()
        elif optname == '--substitute':
            seen.add(optname); opt.substitute = True
        elif optname == '--context-key':
            seen.add(optname); opt.context_key = get_value(); opt.context_key_was_set = True
        elif optname == '--placeholder-format':
            seen.add(optname); opt.placeholder_format = get_value(); opt.placeholder_format_was_set = True
        elif a.startswith('-') and not after_dd:
            tip = f"to pass '{a}' as a value, use '-- {a}'"
            usage_err(f"unexpected argument '{a}' found", tip)
        else:
            positionals.append(a)
        i += 1
    if len(positionals) > 1:
        usage_err(f"unexpected argument '{positionals[1]}' found")
    if positionals:
        opt.input = positionals[0]
    return opt


def strip_toml_comment(line):
    in_str = False; esc = False
    out = []
    for ch in line:
        if in_str:
            out.append(ch)
            if esc:
                esc = False
            elif ch == '\\':
                esc = True
            elif ch == '"':
                in_str = False
        else:
            if ch == '"':
                in_str = True; out.append(ch)
            elif ch == '#':
                break
            else:
                out.append(ch)
    return ''.join(out).strip()

def parse_toml_value(s):
    s = s.strip()
    # The bundled/configured values are TOML strings, arrays of strings, and maps of strings.
    try:
        import ast
        return ast.literal_eval(s)
    except Exception:
        if s.lower() == 'true': return True
        if s.lower() == 'false': return False
        try: return int(s)
        except Exception: return s.strip('"')

def parse_config_file(path):
    cfg = Config()
    section = None
    try:
        with open(path, 'r', encoding='utf-8') as f:
            for raw in f:
                line = strip_toml_comment(raw)
                if not line:
                    continue
                if line.startswith('[') and line.endswith(']'):
                    section = line[1:-1].strip()
                    continue
                if '=' not in line:
                    continue
                key, val = line.split('=', 1)
                key = key.strip()
                if key.startswith('"') and key.endswith('"'):
                    key = parse_toml_value(key)
                valp = parse_toml_value(val)
                if section == 'level_map':
                    cfg.level_map[str(key)] = str(valp)
                elif section is None:
                    if key == 'message_keys': cfg.message_keys = list(valp)
                    elif key == 'time_keys': cfg.time_keys = list(valp)
                    elif key == 'dump_all_exclude': cfg.dump_all_exclude = list(valp)
                    elif key == 'always_print_fields': cfg.always_print_fields = list(valp)
                    elif key == 'level_keys': cfg.level_keys = list(valp)
                    elif key == 'main_line_format': cfg.main_line_format = str(valp)
                    elif key == 'additional_value_format': cfg.additional_value_format = str(valp)
    except Exception:
        raise
    return cfg

def load_config(opt):
    if opt.config_file:
        try:
            return parse_config_file(opt.config_file)
        except Exception:
            panic("src/main.rs:35:50", "Could not load config file.")
    # dirs::config_dir style for this tool: $XDG_CONFIG_HOME/fblog.toml, then ~/.config/fblog.toml
    candidates = []
    xdg = os.environ.get('XDG_CONFIG_HOME')
    if xdg:
        candidates.append(os.path.join(xdg, 'fblog.toml'))
    home = os.environ.get('HOME')
    if home:
        candidates.append(os.path.join(home, '.config', 'fblog.toml'))
    for p in candidates:
        if p and os.path.exists(p):
            try:
                return parse_config_file(p)
            except Exception:
                return Config()
    return Config()


def panic(location, message):
    sys.stderr.write(f"\nthread 'main' panicked at {location}:\n{message}\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n")
    sys.exit(101)


def ansi_bold(s): return BOLD + s + RESET
def ansi_dim(s): return DIM + s + RESET
def ansi_color(code, s): return f"\x1b[{code}m" + s + RESET

def scalar_to_str(v):
    if v is None:
        return ""
    if isinstance(v, bool):
        return "true" if v else "false"
    if isinstance(v, int):
        return str(v)
    if isinstance(v, float):
        if math.isfinite(v) and v.is_integer():
            return str(int(v))
        return format(v, 'g')
    if isinstance(v, str):
        return v
    return ""

def template_value(v):
    if v is None:
        return ""
    if isinstance(v, bool): return "true" if v else "false"
    if isinstance(v, int): return str(v)
    if isinstance(v, float): return format(v, 'g')
    if isinstance(v, str): return v
    if isinstance(v, list):
        return '[' + ', '.join(template_value(x) if not isinstance(x, dict) else '[object]' for x in v) + ']'
    if isinstance(v, dict): return '[object]'
    return str(v)

def dump_value_str(v, quote_string=False):
    if v is None: return 'null'
    if isinstance(v, bool): return 'true' if v else 'false'
    if isinstance(v, int): return str(v)
    if isinstance(v, float): return format(v, 'g')
    if isinstance(v, str):
        if quote_string:
            return json.dumps(v, ensure_ascii=False)
        return v
    return template_value(v)


def parse_int_string(s):
    if re.fullmatch(r'-?\d+', s or ''):
        try: return int(s)
        except Exception: return None
    return None

def format_epoch(n):
    # fblog accepts contemporary Unix seconds and larger millisecond values.  The
    # observed cutoff is in the early 2080s; this mimics the practical behavior.
    try:
        if n > 3555000000:
            ts = n / 1000.0
        else:
            ts = n
        return datetime.datetime.utcfromtimestamp(ts).strftime('%Y-%m-%dT%H:%M:%S')
    except Exception:
        return str(n)

def normalize_time(v):
    if isinstance(v, bool):
        return 'true' if v else 'false'
    if isinstance(v, int):
        return format_epoch(v)
    if isinstance(v, str):
        n = parse_int_string(v)
        if n is not None:
            return format_epoch(n)
        # A timestamp with fractional seconds/timezone is displayed by the default
        # template through fixed_size(19), so returning it as-is is enough.
        return v
    if isinstance(v, float):
        return scalar_to_str(v)
    return ""


def sanitize_key(k):
    s = re.sub(r'[^0-9A-Za-z_]', '_', str(k))
    if not s:
        s = '_'
    if not re.match(r'[A-Za-z_]', s[0]):
        s = '_' + s
    return s

class Leaf:
    __slots__ = ('value', 'quote')
    def __init__(self, value, quote=False):
        self.value = value; self.quote = quote


def flatten_value(v, path='', path_from_array=False, out=None, object_child=True):
    if out is None: out = {}
    if isinstance(v, dict):
        for k in sorted(v.keys(), key=lambda x: str(x)):
            child = v[k]
            if child is None:
                # Object nulls are not included in flattened output.
                continue
            child_path = str(k) if not path else path + ' > ' + str(k)
            flatten_value(child, child_path, False, out, True)
    elif isinstance(v, list):
        for i, child in enumerate(v):
            # Arrays directly contained in arrays use 1-based labels for the inner
            # dimensions, matching the original display.
            idx = i + 1 if path_from_array else i
            child_path = f"{path}[{idx}]" if path else f"[{idx}]"
            if isinstance(child, (dict, list)):
                flatten_value(child, child_path, True, out, False)
            else:
                out[child_path] = Leaf(child, quote=isinstance(child, str))
    else:
        if path:
            out[path] = Leaf(v, quote=(not object_child and isinstance(v, str)))
    return out


def field_matches(request, key):
    return key == request or key.startswith(request + ' >') or key.startswith(request + '[')


def find_value(entry, keys, flat=None):
    if flat is None:
        flat = flatten_value(entry)
    for k in keys:
        if isinstance(entry, dict) and k in entry:
            return entry[k], True
        if k in flat:
            return flat[k].value, True
    return None, False


def split_prefix(line, with_prefix):
    if not with_prefix:
        return '', line, line
    idx = line.find('{')
    if idx < 0:
        return '', None, line
    prefix = line[:idx].rstrip()
    return prefix, line[idx:], line

# ---------------- Minimal Handlebars-like renderer ----------------

def tokenize_expr(expr):
    tokens = []
    i = 0
    while i < len(expr):
        c = expr[i]
        if c.isspace(): i += 1; continue
        if c in '()': tokens.append(c); i += 1; continue
        if c in ('"', "'"):
            q = c; j = i + 1; esc = False; val = c
            while j < len(expr):
                ch = expr[j]; val += ch
                if esc: esc = False
                elif ch == '\\': esc = True
                elif ch == q: break
                j += 1
            tokens.append(val); i = j + 1; continue
        j = i
        while j < len(expr) and (not expr[j].isspace()) and expr[j] not in '()':
            j += 1
        tokens.append(expr[i:j]); i = j
    return tokens

HELPERS = {'uppercase','fixed_size','min_size','bold','color_rgb','cyan','level_style','red','green','yellow','blue','magenta','white','black','lowercase'}

class ExprParser:
    def __init__(self, tokens, ctx):
        self.tokens = tokens; self.i = 0; self.ctx = ctx
    def peek(self):
        return self.tokens[self.i] if self.i < len(self.tokens) else None
    def pop(self):
        t = self.peek(); self.i += 1; return t
    def parse(self):
        if not self.tokens: return ''
        val = self.parse_atom_or_call()
        return val
    def parse_atom_or_call(self):
        tok = self.pop()
        if tok == '(':
            val = self.parse_atom_or_call()
            if self.peek() == ')': self.pop()
            return val
        if tok is None: return ''
        # helper call if helper name, or if a non-helper is followed by arguments -> render error
        if tok in HELPERS:
            return self.call_helper(tok)
        if self.peek() not in (None, ')'):
            # Something like {{unknown_func message}}
            raise RenderError(f"Helper not found {tok}")
        return self.atom(tok)
    def atom(self, tok):
        if tok is None: return ''
        if (tok.startswith('"') and tok.endswith('"')) or (tok.startswith("'") and tok.endswith("'")):
            try:
                import ast
                return str(ast.literal_eval(tok))
            except Exception:
                return tok[1:-1]
        if re.fullmatch(r'-?\d+', tok): return tok
        return template_value(self.ctx.get(tok, ''))
    def arg(self):
        if self.peek() == '(':
            self.pop()
            val = self.parse_atom_or_call()
            if self.peek() == ')': self.pop()
            return val
        return self.parse_atom_or_call()
    def call_helper(self, name):
        if name == 'uppercase': return self.arg().upper()
        if name == 'lowercase': return self.arg().lower()
        if name in ('fixed_size','min_size'):
            n_s = self.arg()
            try: n = int(str(n_s))
            except Exception: n = 0
            s = self.arg()
            if len(s) > n:
                return s[:n]
            if len(s) < n:
                return ' ' * (n-len(s)) + s
            return s
        if name == 'bold': return ansi_bold(self.arg())
        if name == 'color_rgb':
            r = self.arg(); g = self.arg(); b = self.arg(); s = self.arg()
            return f"\x1b[38;2;{int(r)};{int(g)};{int(b)}m" + s + RESET
        if name == 'cyan': return ansi_color('36', self.arg())
        if name in ('red','green','yellow','blue','magenta','white','black'):
            codes = {'black':'30','red':'31','green':'32','yellow':'33','blue':'34','magenta':'35','cyan':'36','white':'37'}
            return ansi_color(codes[name], self.arg())
        if name == 'level_style':
            s = self.arg()
            u = s.strip().upper()
            code = {'DEBUG':'34','INFO':'32','WARN':'33','ERROR':'31','TRACE':'36'}.get(u, '35')
            return f"\x1b[1;{code}m" + s + RESET
        raise RenderError(f"Helper not found {name}")


def eval_expr(expr, ctx):
    tokens = tokenize_expr(expr.strip())
    return ExprParser(tokens, ctx).parse()


def render_template(tpl, ctx, name='main_line'):
    def render_section(s):
        out = []
        pos = 0
        while True:
            start = s.find('{{', pos)
            if start < 0:
                out.append(s[pos:]); break
            out.append(s[pos:start])
            end = s.find('}}', start + 2)
            if end < 0:
                raise RenderError("Unclosed expression")
            tag = s[start+2:end].strip()
            if tag.startswith('#if '):
                var = tag[4:].strip()
                close = '{{/if}}'
                closepos = s.find(close, end+2)
                if closepos < 0:
                    raise RenderError("Unclosed if")
                inner = s[end+2:closepos]
                val = ctx.get(var, '')
                truth = False
                if isinstance(val, str): truth = (val != '')
                elif val is None: truth = False
                else: truth = bool(val)
                if truth:
                    out.append(render_section(inner))
                pos = closepos + len(close)
            elif tag.startswith('/if'):
                pos = end + 2
            else:
                out.append(eval_expr(tag, ctx))
                pos = end + 2
        return ''.join(out)
    return render_section(tpl)

# ---------------- Substitution rendering ----------------

def render_rich(v):
    if isinstance(v, bool):
        return ("\x1b[1;32mtrue" if v else "\x1b[1;31mfalse") + RESET
    if v is None:
        return ansi_bold('null')
    if isinstance(v, (int, float)) and not isinstance(v, bool):
        return "\x1b[1;36m" + scalar_to_str(v) + RESET
    if isinstance(v, str):
        return "\x1b[1;33m" + v + RESET
    if isinstance(v, list):
        parts = [ansi_dim('[')]
        for i, item in enumerate(v):
            if i: parts.append(ansi_dim(', '))
            parts.append(render_rich(item))
        parts.append(ansi_dim(']'))
        return ''.join(parts)
    if isinstance(v, dict):
        parts = [ansi_dim('{')]
        first = True
        for k in sorted(v.keys(), key=lambda x: str(x)):
            if not first: parts.append(ansi_dim(', '))
            first = False
            parts.append("\x1b[35m" + str(k) + RESET)
            parts.append(ansi_dim(': '))
            parts.append(render_rich(v[k]))
        parts.append(ansi_dim('}'))
        return ''.join(parts)
    return ansi_bold(str(v))


def substitute_message(message, context, fmt):
    if not isinstance(message, str):
        return scalar_to_str(message)
    if not isinstance(context, (dict, list)):
        return message
    if 'key' not in fmt:
        panic("src/main.rs:68:23", "Invalid placeholder format: The identifier `key` is missing")
    prefix, suffix = fmt.split('key', 1)
    if prefix == '' and suffix == '':
        pat = re.compile(r'([A-Za-z0-9_]+)')
    else:
        if suffix:
            keypart = r'(.+?)'
            pat = re.compile(re.escape(prefix) + keypart + re.escape(suffix))
        else:
            pat = re.compile(re.escape(prefix) + r'([A-Za-z0-9_]+)')
    def repl(m):
        key = m.group(1)
        found = False; val = None
        if isinstance(context, dict):
            if key in context:
                found = True; val = context[key]
        elif isinstance(context, list):
            try:
                idx = int(key)
                if 0 <= idx < len(context):
                    found = True; val = context[idx]
            except Exception:
                pass
        if found:
            return render_rich(val)
        return ansi_dim(prefix) + "\x1b[1;31m" + key + RESET + ansi_dim(suffix)
    return pat.sub(repl, message)

# ---------------- Lua-ish filters ----------------

class LuaRuntimeError(Exception): pass

class LuaNil:
    def __bool__(self): return False
    def __eq__(self, other): return isinstance(unwrap(other), LuaNil)
    def __ne__(self, other): return not self.__eq__(other)
    def __getattr__(self, name):
        raise LuaRuntimeError(f"attempt to index a nil value (global '{getattr(self, '_name', name)}')")
    def __getitem__(self, item):
        raise LuaRuntimeError("attempt to index a nil value")
    def __repr__(self): return 'nil'
NIL = LuaNil()


def unwrap(v):
    if isinstance(v, LuaValue): return v.v
    return v

class LuaValue:
    def __init__(self, v): self.v = v
    def __bool__(self):
        v = self.v
        if isinstance(v, LuaNil) or v is None: return False
        if isinstance(v, bool): return v
        return True
    def __eq__(self, other):
        a = self.v; b = unwrap(other)
        if isinstance(a, LuaNil): return isinstance(b, LuaNil)
        if isinstance(b, LuaNil): return False
        return a == b
    def __ne__(self, other): return not self.__eq__(other)
    def _cmp(self, other, op):
        a = self.v; b = unwrap(other)
        if isinstance(a, LuaValue): a = a.v
        if isinstance(b, LuaValue): b = b.v
        if (isinstance(a, (int,float)) and not isinstance(a,bool) and isinstance(b, (int,float)) and not isinstance(b,bool)) or (isinstance(a, str) and isinstance(b, str)):
            return op(a,b)
        an = 'number' if isinstance(a,(int,float)) and not isinstance(a,bool) else type(a).__name__
        bn = 'number' if isinstance(b,(int,float)) and not isinstance(b,bool) else type(b).__name__
        if isinstance(a, str): an='string'
        if isinstance(b, str): bn='string'
        raise LuaRuntimeError(f"attempt to compare {an} with {bn}")
    def __lt__(self, other): return self._cmp(other, lambda a,b:a<b)
    def __le__(self, other): return self._cmp(other, lambda a,b:a<=b)
    def __gt__(self, other): return self._cmp(other, lambda a,b:a>b)
    def __ge__(self, other): return self._cmp(other, lambda a,b:a>=b)
    def __getattr__(self, name):
        v = self.v
        if isinstance(v, dict):
            return lua_wrap(v.get(name, NIL))
        if isinstance(v, LuaNil):
            return getattr(v, name)
        raise LuaRuntimeError(f"attempt to index a {type(v).__name__} value")
    def __getitem__(self, item):
        v = self.v
        if isinstance(item, LuaValue): item = item.v
        if isinstance(v, list):
            if isinstance(item, int):
                idx = item - 1
                if 0 <= idx < len(v): return lua_wrap(v[idx])
                return lua_wrap(NIL)
            return lua_wrap(NIL)
        if isinstance(v, dict):
            return lua_wrap(v.get(item, NIL))
        if isinstance(v, LuaNil):
            return v.__getitem__(item)
        raise LuaRuntimeError(f"attempt to index a {type(v).__name__} value")
    def __len__(self):
        if isinstance(self.v, (str, list, dict)): return len(self.v)
        return 0
    def __repr__(self): return repr(self.v)


def lua_wrap(v):
    if isinstance(v, LuaValue): return v
    if v is None:
        return LuaValue("unsupported")
    if isinstance(v, dict):
        return LuaValue({str(k): lua_plain(val) for k,val in v.items()})
    if isinstance(v, list):
        return LuaValue([lua_plain(x) for x in v])
    return LuaValue(v)

def lua_plain(v):
    if v is None: return "unsupported"
    if isinstance(v, dict): return {str(k): lua_plain(val) for k,val in v.items()}
    if isinstance(v, list): return [lua_plain(x) for x in v]
    return v

class Env(dict):
    def __missing__(self, key):
        n = LuaNil(); n._name = key
        self[key] = n
        return n

class LuaStringLib:
    def find(self, s, pat):
        sv = unwrap(s); pv = unwrap(pat)
        if sv is None or isinstance(sv, LuaNil): return NIL
        try:
            m = re.search(str(pv), str(sv))
        except Exception:
            m = re.search(re.escape(str(pv)), str(sv))
        if not m: return NIL
        return LuaValue(m.start()+1)
    def len(self, s): return LuaValue(len(str(unwrap(s))))
    def match(self, s, pat):
        sv = str(unwrap(s)); pv = str(unwrap(pat))
        try: m = re.search(pv, sv)
        except Exception: m = re.search(re.escape(pv), sv)
        return LuaValue(m.group(0)) if m else NIL


def lua_len(x): return LuaValue(len(x) if hasattr(x, '__len__') else 0)


def lua_literal(v):
    v = unwrap(v)
    if isinstance(v, LuaNil): return 'nil'
    if v is None: return '"unsupported"'
    if isinstance(v, bool): return 'true' if v else 'false'
    if isinstance(v, (int,float)) and not isinstance(v,bool): return scalar_to_str(v)
    if isinstance(v, str): return json.dumps(v, ensure_ascii=False)
    if isinstance(v, list): return '{' + ','.join(lua_literal(x) for x in v) + '}'
    if isinstance(v, dict):
        parts=[]
        for k in sorted(v.keys(), key=lambda x: str(x)):
            parts.append(f"{sanitize_key(k)} = {lua_literal(v[k])}")
        return '{' + ','.join(parts) + '}'
    return json.dumps(str(v))


def make_lua_env(entry):
    env = Env()
    names = []
    for k, v in entry.items():
        name = sanitize_key(k)
        env[name] = lua_wrap(v)
        names.append(name)
    env['nil'] = NIL
    env['true'] = LuaValue(True)
    env['false'] = LuaValue(False)
    env['string'] = LuaStringLib()
    env['lua_len'] = lua_len
    return env, sorted(set(names))


def translate_lua(expr, no_implicit=False):
    e = expr.strip()
    if e.startswith('return '):
        if not no_implicit:
            raise SyntaxError("unexpected symbol near 'return'")
        e = e[7:].strip()
    # For this reimplementation expressions are evaluated directly.
    e = e.replace('~=', '!=')
    e = re.sub(r'#\s*([A-Za-z_][A-Za-z0-9_]*)', r'lua_len(\1)', e)
    return e


def filter_error(err):
    # Close to the mlua Debug formatting used by the original.
    msg = str(err)
    if isinstance(err, SyntaxError):
        detail = f"SyntaxError {{ message: \"src/filter.rs:23:1: {msg}\", incomplete_input: false }}"
    else:
        detail = f"RuntimeError(\"src/filter.rs:23:1: {msg}\\nstack traceback:\\n\\t[C]: in metamethod 'index'\\n\\tsrc/filter.rs:23:1: in main chunk\")"
    sys.stderr.write(f"\x1b[31mFailed to apply filter expression\x1b[0m: '{detail}'\n")


def apply_filter(expr, entry, print_lua=False, no_implicit=False):
    env, names = make_lua_env(entry)
    if print_lua:
        for n in names:
            sys.stdout.write(f"{n} = {lua_literal(env[n])}\n")
    if not expr:
        return True
    try:
        code = translate_lua(expr, no_implicit)
        res = eval(code, {'__builtins__': {}}, env)
        return bool(res)
    except SyntaxError as e:
        filter_error(e)
        return False
    except LuaRuntimeError as e:
        filter_error(e)
        return False
    except Exception as e:
        filter_error(e)
        return False

# ---------------- Main processing ----------------

def build_context(entry, flat, cfg, opt):
    msg_keys = opt.message_keys + cfg.message_keys
    time_keys = opt.time_keys + cfg.time_keys
    level_keys = opt.level_keys + cfg.level_keys
    msg_val, _ = find_value(entry, msg_keys, flat)
    time_val, _ = find_value(entry, time_keys, flat)
    level_val, found_level = find_value(entry, level_keys, flat)

    fblog_message_raw = scalar_to_str(msg_val)
    fblog_timestamp = normalize_time(time_val)
    if found_level and not isinstance(level_val, (dict, list)) and level_val is not None:
        fblog_level = scalar_to_str(level_val)
    else:
        fblog_level = 'unknown'
    # level maps: configuration map first, then CLI overrides were already merged into cfg.level_map
    fblog_level = cfg.level_map.get(fblog_level, fblog_level)

    ctx = {}
    for k, v in entry.items():
        ctx[str(k)] = v
        ctx[sanitize_key(k)] = v
    ctx['fblog_message'] = fblog_message_raw
    ctx['fblog_timestamp'] = fblog_timestamp
    ctx['fblog_level'] = fblog_level
    return ctx, msg_val


def process_entry(entry, prefix, original_line, cfg, opt):
    flat = flatten_value(entry)
    if opt.filter_expr is not None:
        if not apply_filter(opt.filter_expr, entry, opt.print_lua, opt.no_implicit_filter_return_statement):
            return

    ctx, msg_val = build_context(entry, flat, cfg, opt)
    ctx['fblog_prefix'] = prefix or ''

    substitute_active = opt.substitute or opt.context_key_was_set or opt.placeholder_format_was_set
    context_key = opt.context_key if opt.context_key is not None else 'context'
    placeholder_fmt = opt.placeholder_format if opt.placeholder_format is not None else '{key}'
    if substitute_active:
        context_val = entry.get(context_key)
        ctx['fblog_message'] = substitute_message(msg_val, context_val, placeholder_fmt)

    try:
        line = render_template(cfg.main_line_format, ctx, 'main_line')
    except RenderError as e:
        sys.stdout.write(f"{BOLD_RED}??? >{RESET} Failed to process line: Error rendering \"main_line\" line 1, col 1: {e}\n")
        return
    sys.stdout.write(line + '\n')

    excludes = list(cfg.dump_all_exclude) + opt.excluded
    add_items = []
    if opt.dump_all or opt.excluded:
        for k in sorted(flat.keys()):
            if k in excludes: continue
            add_items.append((k, flat[k]))
    else:
        fields = list(cfg.always_print_fields) + opt.additional
        for req in fields:
            for k in sorted(flat.keys()):
                if field_matches(req, k):
                    add_items.append((k, flat[k]))
    for k, leaf in add_items:
        avctx = dict(ctx)
        avctx['key'] = k
        avctx['value'] = dump_value_str(leaf.value, leaf.quote)
        try:
            sys.stdout.write(render_template(cfg.additional_value_format, avctx, 'additional_value') + '\n')
        except RenderError as e:
            sys.stdout.write(f"{BOLD_RED}??? >{RESET} Failed to process line: Error rendering \"additional_value\" line 1, col 1: {e}\n")


def print_unparsed(line):
    sys.stdout.write(f"{BOLD_ORANGE}??? >{RESET} {line}\n")

def print_read_error():
    sys.stdout.write(f"{BOLD_RED}??? >{RESET} Could not read line: stream did not contain valid UTF-8\n")


def read_lines_binary(stream):
    for b in stream:
        if b.endswith(b'\n'): b = b[:-1]
        if b.endswith(b'\r'): b = b[:-1]
        try:
            yield b.decode('utf-8'), None
        except UnicodeDecodeError:
            yield None, 'utf8'


def main(argv):
    opt = parse_args(argv)
    cfg = load_config(opt)
    if opt.main_line_format is not None:
        cfg.main_line_format = opt.main_line_format
    if opt.additional_value_format is not None:
        cfg.additional_value_format = opt.additional_value_format
    for frm, to in opt.map_levels:
        cfg.level_map[frm] = to
    if opt.excluded:
        opt.dump_all = True

    # Placeholder format is validated lazily by the original; validate before processing.
    if (opt.substitute or opt.context_key_was_set or opt.placeholder_format_was_set):
        pf = opt.placeholder_format if opt.placeholder_format is not None else '{key}'
        if 'key' not in pf:
            panic("src/main.rs:68:23", "Invalid placeholder format: The identifier `key` is missing")

    if opt.input == '-':
        stream = sys.stdin.buffer
        close = False
    else:
        try:
            stream = open(opt.input, 'rb')
            close = True
        except Exception:
            panic("src/main.rs:105:68", f"Can't open file: {opt.input}")
    try:
        for line, err in read_lines_binary(stream):
            if err:
                print_read_error(); continue
            prefix, json_part, orig = split_prefix(line, opt.with_prefix)
            if json_part is None:
                print_unparsed(orig); continue
            try:
                obj = json.loads(json_part)
            except Exception:
                print_unparsed(orig); continue
            if not isinstance(obj, dict):
                print_unparsed(orig); continue
            process_entry(obj, prefix, orig, cfg, opt)
    finally:
        if close:
            stream.close()

if __name__ == '__main__':
    main(sys.argv[1:])
